// The second built-in sample (docs/sample-project.md): Lu Xun's 阿Q正传, taken
// apart as an author would set it up in Drifting, and left half written. The
// first six chapters are the 1948 Complete Works text in ./a-q/text.json
// (generated by scripts/build-a-q-sample.py); chapters seven to nine are
// planned, with their summaries, for the author to write. Everything around the
// text was written for the sample and checked against the novel.

import type { BookChapter } from './book';
import type { SampleBook } from './sample-book';
import bookText from './a-q/text.json';

export const A_Q_PROJECT_NAME = '阿Q正传（示例）';

interface TextChapter extends BookChapter { title: string }

const WRITTEN = (bookText as { chapters: TextChapter[] }).chapters;
const NUMERALS = ['一', '二', '三', '四', '五', '六', '七', '八', '九'];
const TITLES = [...WRITTEN.map((chapter) => chapter.title), '革命', '不准革命', '大团圆'];

/** Nine chapters: the six written, then three planned ones, each one empty paragraph as a new chapter opens. */
export const A_Q_CHAPTERS: readonly BookChapter[] = TITLES.map((_, index) => ({
  number: index + 1,
  roman: NUMERALS[index],
  blocks: WRITTEN[index]?.blocks ?? [''],
}));

const VICTORY = 'victory', VILLAGE = 'village', LIVING = 'living', REVOLUTION = 'revolution';

